// Ініціатива (модифікатор Спритності) і середні хіти
export const monInit = (m) => Math.floor(((m.ab || [10, 10])[1] - 10) / 2);
export const monLabel = (m, li) => (Array.isArray(m.n) ? m.n[li] || m.n[0] : m.n);
